type": ["string", "null"]}}, "required": ["evidence_id", "scope", "source_type", "source_id", "source_version", "observed_at", "location", "title", "authorized_actions"], "type": "object"}, "type": "array"}, "schema_version": {"const": "1.0", "type": "string"}, "warnings": {"items": {"type": "string"}, "type": "array"}}, "required": ["business_status", "schema_version", "data", "warnings", "evidence_refs"], "type": "object"}, "parameters": {}, "stream": false, "tools": [{"function": {"description": "查询城市一天的真实天气预报。未指定城市默认北京，未指定日期默认明天。", "name": "tool_0", "parameters": {"additionalProperties": false, "properties": {"city": {"default": "北京", "description": "城市名称，默认北京", "maxLength": 80, "title": "City", "type": "string"}, "day": {"default": "明天", "description": "今天、明天、后天或 YYYY-MM-DD，默认明天", "maxLength": 10, "title": "Day", "type": "string"}}, "title": "daily_weatherArguments", "type": "object"}}, "type": "function"}]}}' AS JSONB) AS anon_11
