_max_ms\":{\"anyOf\":[{\"type\":\"number\"},{\"type\":\"null\"}],\"title\":\"Wind Speed Max Ms\"}},\"required\":[\"city\",\"date\",\"timezone\",\"latitude\",\"longitude\",\"weather_code\",\"temperature_min_c\",\"temperature_max_c\",\"precipitation_probability_percent\",\"precipitation_mm\",\"wind_speed_max_ms\",\"source\",\"source_url\",\"retrieved_at\"],\"title\":\"DailyWeather\",\"type\":\"object\"},\"resource_id\":\"cca859fa7606fe627a7a090a4d0704bf375895e597bc841e8165e2e5dbcd995b\",\"resource_name\":\"每日天气查询\",\"resource_type\":\"tool\",\"state\":\"DRAFT\",\"version_id\":\"cca859fa7606fe627a7a090a4d0704bf375895e597bc841e8165e2e5dbcd995b\",\"version_label\":\"当前配置\"}]}", "purpose": "debug", "scope": {"channel_id": "channel_407de822881947339e26ec7d9d55a8a0", "environment": "dev", "subject_id": null, "subject_type": null}, "snapshot_id": "runtime_0f654f1230ce3acf445193671f0fd7aa58e61c5f8e6517c5", "source_revision": 1, "source_version_id": "runtime_0f654f1230ce3acf445193671f0fd7aa58e61c5f8e6517c5"}' AS JSONB) AS anon_11
